def product_of_primes(max_value):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    primes = [num for num in range(2, max_value + 1) if is_prime(num)]

    product = 1
    for prime in primes:
        product *= prime

    return product
