import unittest
from mock import patch

# Assume updateInventory is part of an inventory_module
from inventory_module import updateInventory

class TestInventorySystem(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.initial_db_state = {
            'product_1': 10,
            'product_2': 5,
            'product_3': 0
        }

    def reset_mockDB(self):
        # Assume mockDB is a dictionary-like object representing the database state
        self.mockDB.clear()
        self.mockDB.update(self.initial_db_state)

    @patch('inventory_module.mockDB', new_callable=dict)
    def test_add_product_quantity(self, mockDB):
        self.mockDB = mockDB
        updateInventory('product_1', 5)
        self.assertEqual(self.mockDB['product_1'], 15)

    @patch('inventory_module.mockDB', new_callable=dict)
    def test_remove_product_quantity(self, mockDB):
        self.mockDB = mockDB
        updateInventory('product_2', -3)
        self.assertEqual(self.mockDB['product_2'], 2)

    @patch('inventory_module.mockDB', new_callable=dict)
    def test_update_product_to_zero(self, mockDB):
        self.mockDB = mockDB
        updateInventory('product_3', 10)  # Adding first
        updateInventory('product_3', -10)  # Removing back to zero
        self.assertEqual(self.mockDB['product_3'], 0)

    @patch('inventory_module.mockDB', new_callable=dict)
    def test_invalid_product_handling(self, mockDB):
        self.mockDB = mockDB
        updateInventory('non_existent_product', 5)
        self.assertNotIn('non_existent_product', self.mockDB)

def load_and_run_tests():
    suite = unittest.TestLoader().loadTestsFromTestCase(TestInventorySystem)
    runner = unittest.TextTestRunner()
    runner.run(suite)

if __name__ == '__main__':
