def extract_sequence_number(line):
    parts = line.split('/')
    for part in parts:
        if part.isdigit():
            return int(part)
    return None

def sort_file_and_extract_sequence_number(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()

        # Sort lines in reverse order
        sorted_lines = sorted(lines, reverse=True)

        if sorted_lines:
            first_line = sorted_lines[0].strip()
            sequence_number = extract_sequence_number(first_line)

            if sequence_number is not None:
                print(f""First line: {first_line}"")
                print(f""Sequence number: {sequence_number}"")
            else:
                print(""No valid sequence number found in the first line."")
        else:
            print(""File is empty."")

    except FileNotFoundError:
        print(f""Error: The file '{file_path}' was not found."")
    except Exception as e:
        print(f""An error occurred: {e}"")

# Example usage
