    response = requests.post(server_url, json=json_objects, headers=headers)

    if response.status_code == 200:
        print(""Data successfully posted to the server."")
    else:
        print(f""Failed to post data. Status code: {response.status_code}, Response: {response.text}"")

if __name__ == ""__main__"":
    number_of_items = 10  # Set desired number of JSON objects
    json_objects = generate_json_objects(number_of_items)

    web_server_url = ""https://your-server.com/endpoint""  # Replace with actual server URL
    post_to_server(json_objects, web_server_url)
