        num = int(input(""Enter a positive integer: ""))
        if num < 0:
            raise ValueError(""Negative numbers are not allowed."")
        result = factorial(num)
        print(f""The factorial of {num} is {result}."")
    except ValueError as e:
        print(e)

if __name__ == ""__main__"":
