import random
import time
import threading

class CryptoInfo:
    def __init__(self, function_name, delay_min, delay_max):
        self.function_name = function_name
        self.delay_min = delay_min
        self.delay_max = delay_max

class CryptographicService:
    def __init__(self):
        self.crypto_info_list = [
            CryptoInfo(""SHA_256_FUNCTION"", 0.1, 0.5),
            CryptoInfo(""AES_256_FUNCTION"", 0.2, 1)
        ]

    def start_and_stop_cryptographic_service(self):
        service_manager = ServiceManager(self.crypto_info_list)
        executor_service = ExecutorService()
        while True:
            for info in self.crypto_info_list:
                service_manager.start_service(info.function_name)
                executor_service.execute(
                    service_manager.get_thread(info), info.delay_min, info.delay_max
                )
            time.sleep(60)  # Sleep for a minute before checking again

class ServiceManager:
    def __init__(self, crypto_info_list):
        self.crypto_info_list = crypto_info_list

    def start_service(self, function_name):
        print(f""Starting {function_name} service..."")

    def get_thread(self, info):
        if info.function_name == ""SHA_256_FUNCTION"":
            return SHA_256_Thread()
        elif info.function_name == ""AES_256_FUNCTION"":
            return AES_256_Thread()

class ExecutorService:
    def execute(self, thread_obj, delay_min, delay_max):
        random_delay = random.uniform(delay_min, delay_max)
        print(f""Delaying by {random_delay} seconds..."")
        time.sleep(random_delay)
        thread_obj.run()

class SHA_256_Thread(threading.Thread):
    def run(self):
        print(""SHA-256 operation is running"")

class AES_256_Thread(threading.Thread): 
    def run(self): 
        print(""AES-256 operation is running"")
