        img = qr.make_image(fill='black', back_color='white')
        return img
    except Exception as e:
        print(f""Error generating QR code: {e}"")
        log_attempt(data, ""Failed - QR Generation Error"")
        return None

def handle_login(username):
    if not username or len(username) > 20:
        log_attempt(username, ""Failed - Invalid Username"")
        return generate_qr_code(""Invalid User"")

    try:
        qr_image = generate_qr_code(f""User: {username}"")
        if qr_image:
            filename = f""{username}_{datetime.now().strftime('%Y%m%d%H%M%S')}.png""
            qr_image.save(filename)
            log_attempt(username, ""Success"")
            print(f""QR code generated and saved as {filename}"")
    except PermissionError:
        log_attempt(username, ""Failed - Insufficient Permissions"")
        print(""Insufficient permissions to save QR code."")
    except Exception as e:
        log_attempt(username, f""Failed - {str(e)}"")
        print(f""An unexpected error occurred: {e}"")

def main():
    usernames = [""user1"", ""invalid_user!"", """", ""user2""]

    for username in usernames:
        handle_login(username)

if __name__ == ""__main__"":
    if not os.path.exists(LOG_FILE):
        with open(LOG_FILE, ""w"") as log:
            pass
    main()
