import threading
import time
from typing import Callable, Any

class BackgroundTaskExecutor:
    """"""
    A class that executes a given function in the background and monitors its execution.
    Returns True if the function finishes successfully, False otherwise.
    """"""

    def __init__(self, func: Callable, args: Any = None, kwargs: dict = None):
        self.func = func
        self.args = args if args else []
        self.kwargs = kwargs if kwargs else {}
        self.result = False

    def run(self) -> bool:
        def target():
            try:
                self.result = self.func(*self.args, **self.kwargs)
                print(f""Function {self.func.__name__} finished successfully."")
            except Exception as e:
                print(f""Function {self.func.__name__} encountered an error: {str(e)}"")

        thread = threading.Thread(target=target)
        thread.start()

        while thread.is_alive():
            time.sleep(0.1)

        return self.result

def delayed_division(a: int, b: int) -> float:
    time.sleep(2)  # Simulate a delay
    if b == 0:
        raise ZeroDivisionError(""Denominator cannot be zero."")
    return a / b
