### Python Code

```python
import hashlib
import os

def generate_fibonacci(max_value):
    sequence = []
    a, b = 0, 1
    while a <= max_value:
        sequence.append(a)
        a, b = b, a + b
    return sequence

def sum_even_numbers(sequence):
    return sum(x for x in sequence if x % 2 == 0)

def compute_md5(file_path):
    hasher = hashlib.md5()
    try:
        with open(file_path, 'rb') as f:
            while chunk := f.read(8192):
                hasher.update(chunk)
    except FileNotFoundError:
        return None
    return hasher.hexdigest()

# Example usage (this would be run server-side, not in the web client's browser)
if __name__ == ""__main__"":
    fib_sequence = generate_fibonacci(1000)
    print(f""Sum of even Fibonacci numbers: {sum_even_numbers(fib_sequence)}"")

    # List of JavaScript files to compute MD5 for
    js_files = ['script1.js', 'script2.js']

    md5_hashes = {}
    for file in js_files:
        hash_value = compute_md5(file)
        if hash_value:
            md5_hashes[file] = hash_value

    print(""MD5 Hashes of JavaScript files:"", md5_hashes)

