def generate_apdt_array(num_structures, seed_start, min_bit_depth, max_bit_depth):
    apdt_array = []

    for i in range(num_structures):
        try:
            # Seed the random number generator to ensure unique sample rates
            random.seed(seed_start + i)

            # Generate a unique sample rate (e.g., between 8000 and 192000 Hz)
            sample_rate = random.randint(8000, 192000)

            # Randomly assign a bit depth within the specified range
            bit_depth = random.randint(min_bit_depth, max_bit_depth)

            apdt_array.append(AudioProcessingDataStructure(sample_rate, bit_depth))

        except Exception as e:
            return f""Error creating structure: {e}""

    return apdt_array

# Example usage
