def process_order():
    data = request.get_json()

    if not data or 'email' not in data or 'products' not in data or 'order_type' not in data:
        return jsonify({'error': 'Invalid input'}), 400

    email = data['email']
    products = data['products']
    order_type = data['order_type']

    if not is_valid_email(email):
        return jsonify({'error': 'Invalid email'}), 400

    if not isinstance(products, list) or not all(isinstance(p, str) for p in products):
        return jsonify({'error': 'Products must be a list of strings'}), 400

    if order_type not in ['purchase', 'subscription']:
        return jsonify({'error': 'Invalid order type'}), 400

    try:
        # Call the service layer to handle the order
        confirmation = handle_order_request(email, products, order_type)
        return jsonify({'confirmation': confirmation}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

def handle_order_request(email, products, order_type):
    # Simulate service layer handling
    # This function would typically interact with databases or other services
    return f""Order for {order_type} confirmed for email: {email}, products: {products}""

if __name__ == '__main__':
    app.run(debug=True)
