def unique_palindromic_substrings_with_filter(lst, min_length=3):
    """"""
    Accepts a list of strings and returns the count of unique palindromic substrings.
    Uses dynamic programming to efficiently manage space complexity.

    :param lst: List of strings
    :param min_length: Minimum length for substrings to be considered (default is 3)
    :return: Count of unique palindromic substrings with specified minimum length
    """"""

    def is_palindrome(s):
        return s == s[::-1]

    def count_unique_palindromes(s, dp):
        if not s or len(s) < min_length:
            return 0
        if dp.get(s) is not None:
            return dp[s]

        count = set()
        for i in range(len(s)):
            if is_palindrome(s[i:]):
                count.add(s[i:])
            if i > 0 and is_palindrome(s[i-1:i+1]):
                count.update(count_unique_palindromes(s[i+1:], dp))

        dp[s] = len(count)
        return len(count)

    unique_counts = {}

    for word in lst:
        filtered_substrings = {word[i:j] for i in range(len(word)) 
                               for j in range(i+min_length, len(word)+1)}

        dp = {}
        count = 0
        for substring in filtered_substrings:
            count += count_unique_palindromes(substring, dp)

        unique_counts[word] = count

    return sum(unique_counts.values())

