         # Additional scenario with filter on minimum length of substrings
         ([""abc"", ""aabbcc"", ""abbaa""], 8),
         ([""aba"", ""aaabaaa""], 7)
     ]

    for words, expected in test_cases:
        result = unique_palindromic_substrings_with_filter(words)
        assert result == expected, f""Expected {expected}, but got {result}.""

