def read_integers_from_file(file_path):
    try:
        with open(file_path, 'r') as file:
            numbers = [int(line.strip()) for line in file]
        return numbers
    except FileNotFoundError:
        print(f""Error: The file '{file_path}' was not found."")
        exit(1)
    except ValueError:
        print(""Error: The file contains non-integer values."")
        exit(1)

def calculate_sum_of_even_numbers(numbers):
    return sum(number for number in numbers if number % 2 == 0)

def write_result_to_file(file_path, result):
    try:
        with open(file_path, 'w') as file:
            file.write(str(result))
    except Exception as e:
        print(f""Error: Unable to write to the file '{file_path}'. {e}"")
        exit(1)

def main():
    input_file = ""input.txt""
    output_file = ""output.txt""

    numbers = read_integers_from_file(input_file)
    result = calculate_sum_of_even_numbers(numbers)
    write_result_to_file(output_file, result)
    print(f""The sum of even numbers has been written to '{output_file}'."")

if __name__ == ""__main__"":
