import os
import zipfile

def compress_directory_to_zip(directory_path, output_archive_name):
    try:
        with zipfile.ZipFile(output_archive_name, 'w', zipfile.ZIP_DEFLATED) as archive:
            for root, _, files in os.walk(directory_path):
                for file in files:
                    file_path = os.path.join(root, file)
                    try:
                        archive.write(file_path, os.path.relpath(file_path, start=directory_path))
                    except Exception as e:
                        # Log the error if needed
                        continue  # Skip problematic files

        return 0
    except Exception as e:
        # Optionally log the exception here for debugging purposes
        return 1
