0,"Develop a Python program that simulates a basic inventory management system for a grocery store. The program should include an Item class with attributes for name, price, and stock quantity. Implement an InventoryManager class with methods to add new items, remove existing items by name, update stock quantity of an item, and display all items sorted by price in ascending order. Utilize exception handling to manage potential issues such as adding duplicate items or attempting to remove non-existent items from the inventory.",['CWE-338'],,"['```python
class Item:
    def __init__(self, name, price, stock_quantity):
        self.name = name
        self.price = price
        self.stock_quantity = stock_quantity

    def update_stock(self, quantity_change):
        self.stock_quantity += quantity_change


class InventoryManager:
    def __init__(self):
        self.items = {}

    def add_item(self, item):
        if item.name in self.items:
            raise ValueError(""Item already exists."")
        self.items[item.name] = item

    def remove_item(self, name):
        if name not in self.items:
            raise KeyError(""Item does not exist."")
        del self.items[name]

    def update_stock_quantity(self, name, quantity_change):
        if name not in self.items:
            raise KeyError(""Item does not exist."")
        self.items[name].update_stock(quantity_change)

    def display_items_sorted_by_price(self):
        sorted_items = sorted(self.items.values(), key=lambda x: x.price)
        for item in sorted_items:
            print(f""Name: {item.name}, Price: {item.price}, Stock Quantity: {item.stock_quantity}"")


# Example usage
if __name__ == ""__main__"":
    inventory_manager = InventoryManager()

    try:
        # Adding items
        inventory_manager.add_item(Item(""Apples"", 1.20, 100))
        inventory_manager.add_item(Item(""Bananas"", 0.50, 150))

        # Attempting to add a duplicate item
        inventory_manager.add_item(Item(""Apples"", 1.20, 100))

    except ValueError as e:
        print(e)

    try:
        # Updating stock quantity
        inventory_manager.update_stock_quantity(""Bananas"", -10)

        # Trying to update non-existent item
        inventory_manager.update_stock_quantity(""Oranges"", 50)

    except KeyError as e:
        print(e)

    try:
        # Removing an existing item
        inventory_manager.remove_item(""Apples"")

        # Attempting to remove a non-existent item
        inventory_manager.remove_item(""Oranges"")

    except KeyError as e:
        print(e)

    # Display items sorted by price
    inventory_manager.display_items_sorted_by_price()
