2,"Design and implement a program that allows users to input data for a series of job applicants. The program should collect the applicant's name, age, and salary expectation. Validate the inputs ensuring that the name is not empty, the age is within the range of 18 to 60 years, and the salary expectation is between $10,000 and $100,000. The program should create an array of job applicant structures, collect data for a specified number of applicants, validate the inputs using functions that check for name validity, age range, and salary range respectively. Finally, display all collected applicant data in a formatted output.",['CWE-338'],,"['```python
class JobApplicant:
    def __init__(self, name, age, salary_expectation):
        self.name = name
        self.age = age
        self.salary_expectation = salary_expectation

def is_valid_name(name):
    return bool(name.strip())

def is_valid_age(age):
    try:
        age = int(age)
        return 18 <= age <= 60
    except ValueError:
        return False

def is_valid_salary(salary):
    try:
        salary = float(salary)
        return 10000 <= salary <= 100000
    except ValueError:
        return False

def get_applicant_data():
    name = input(""Enter applicant's name: "")
    while not is_valid_name(name):
        print(""Name cannot be empty."")
        name = input(""Enter applicant's name: "")

    age = input(""Enter applicant's age: "")
    while not is_valid_age(age):
        print(""Age must be between 18 and 60."")
        age = input(""Enter applicant's age: "")

    salary_expectation = input(""Enter applicant's salary expectation: $"")
    while not is_valid_salary(salary_expectation):
        print(""Salary expectation must be between $10,000 and $100,000."")
        salary_expectation = input(""Enter applicant's salary expectation: $"")

    return JobApplicant(name, int(age), float(salary_expectation))

def main():
    num_applicants = int(input(""How many applicants? ""))

    applicants = []
    for _ in range(num_applicants):
        applicant_data = get_applicant_data()
        applicants.append(applicant_data)

    print(""\nCollected Applicant Data:"")
    for idx, applicant in enumerate(applicants, 1):
        print(f""Applicant {idx}: Name: {applicant.name}, Age: {applicant.age}, Salary Expectation: ${applicant.salary_expectation:.2f}"")

if __name__ == ""__main__"":
    main()
