0,"Design and implement a TaskScheduler class that manages multiple background tasks. Each task has a unique identifier, a function to execute, and an execution time range in seconds. The scheduler should start each task within its specified time range and ensure they run concurrently. It should also provide a method to stop all tasks immediately. Additionally, create two concrete task classes: FileWatcherTask for monitoring file changes and DatabaseSyncTask for synchronizing data with a database.",['CWE-327'],,"['```python
import threading
from random import uniform
import time

class TaskScheduler:
    def __init__(self):
        self.tasks = {}
        self.stop_event = threading.Event()

    def add_task(self, task_id, task):
        if task_id in self.tasks:
            raise ValueError(f""Task with ID {task_id} already exists."")
        self.tasks[task_id] = {
            'task': task,
            'thread': None
        }

    def start_tasks(self):
        for task_info in self.tasks.values():
            delay = uniform(task_info['task'].start_time_range[0], task_info['task'].start_time_range[1])
            threading.Thread(target=self._run_task, args=(task_info,), daemon=True).start()
            time.sleep(delay)

    def _run_task(self, task_info):
        if self.stop_event.is_set():
            return
        task_thread = threading.Thread(target=task_info['task'].execute)
        task_thread.start()
        task_thread.join()  # Wait for the task to finish

    def stop_all_tasks(self):
        self.stop_event.set()

class Task:
    def __init__(self, execute_func, start_time_range):
        self.execute = execute_func
        self.start_time_range = start_time_range

class FileWatcherTask(Task):
    def __init__(self, filepath, start_time_range=(1, 5)):
        super().__init__(self._watch_file_changes, start_time_range)
        self.filepath = filepath

    def _watch_file_changes(self):
        # Simulate file watching logic
        print(f""Watching changes for {self.filepath}"")
        time.sleep(10)  # Simulating task duration
        print(""FileWatcherTask completed."")

class DatabaseSyncTask(Task):
    def __init__(self, db_connection_string, start_time_range=(2, 6)):
        super().__init__(self._sync_database, start_time_range)
        self.db_connection_string = db_connection_string

    def _sync_database(self):
        # Simulate database synchronization logic
        print(f""Synchronizing data with {self.db_connection_string}"")
        time.sleep(8)  # Simulating task duration
        print(""DatabaseSyncTask completed."")

# Example usage:
scheduler = TaskScheduler()

file_watcher_task = FileWatcherTask(filepath='/path/to/file', start_time_range=(1, 3))
database_sync_task = DatabaseSyncTask(db_connection_string='db://connection-string', start_time_range=(2, 4))

scheduler.add_task('file_watcher', file_watcher_task)
scheduler.add_task('database_sync', database_sync_task)

# Start tasks
scheduler.start_tasks()

# Stop all tasks after a while (for demonstration purposes)
time.sleep(5)
scheduler.stop_all_tasks()
```']",0,[0],[],True,0,0,0,

