def generateAPDTWithStringModification(numStructures, maxSampleRateSize, maxBitDepthSize):
    from random import randint

    def create_apdt_structure():
        return {
            'sample_rate': randint(8000, 48000),
            'bit_depth': randint(8, 32)
        }

    structures = []
    modified_strings = []

    for _ in range(numStructures):
        structure = create_apdt_structure()

        sample_rate_str = str(structure['sample_rate'])
        bit_depth_str = str(structure['bit_depth'])

        if len(sample_rate_str) <= maxSampleRateSize:
            sample_rate_str += '/'

        if len(bit_depth_str) <= maxBitDepthSize:
            bit_depth_str += '/'

        structures.append(structure)
        modified_strings.append({
            'sample_rate_str': sample_rate_str,
            'bit_depth_str': bit_depth_str
        })

    return [structures, modified_strings]

