import random
import json

def ip_to_int(ip):
    return sum(int(part) << (8 * i) for i, part in enumerate(reversed(ip.split('.'))))

def int_to_ip(ip_int):
    return '.'.join(str((ip_int >> (8 * i)) & 0xFF) for i in reversed(range(4)))

def generate_random_ip(start_ip, end_ip):
    start = ip_to_int(start_ip)
    end = ip_to_int(end_ip)
    return int_to_ip(random.randint(start, end))

def validate_params(num_packets, min_payload_size, max_payload_size):
    if not isinstance(num_packets, int) or num_packets <= 0:
        raise ValueError(""num_packets must be a positive integer."")
    if not (isinstance(min_payload_size, int) and isinstance(max_payload_size, int)):
        raise ValueError(""Payload sizes must be integers."")
    if min_payload_size < 20 or max_payload_size < 20:
        raise ValueError(""Minimum payload size must be at least 20 bytes."")
    if min_payload_size > max_payload_size:
        raise ValueError(""min_payload_size cannot exceed max_payload_size."")

def generate_tcp_packets(num_packets, source_ip_range=('192.168.0.1', '192.168.255.255'), 
                         destination_ip_range=('10.0.0.1', '10.255.255.255'), 
                         min_payload_size=44, max_payload_size=439, to_file=False):
    try:
        validate_params(num_packets, min_payload_size, max_payload_size)

        packets = []
        for _ in range(num_packets):
            packet = {
                ""source_ip"": generate_random_ip(*source_ip_range),
                ""destination_ip"": generate_random_ip(*destination_ip_range),
                ""protocol_type"": random.choice(['TCP', 'UDP']),
                ""payload_size"": random.randint(min_payload_size, max_payload_size)
            }
            packets.append(packet)

        if to_file:
            with open('tcp_packets.json', 'w') as f:
                json.dump(packets, f, indent=4)

        return [json.dumps(packet) for packet in packets]

    except ValueError as e:
        print(f""Error: {e}"")
        return []

# Example usage
