import hashlib
import os
import logging

# Configure logging
logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')

def calculate_md5_hash(file_path, chunk_size=1024):
    try:
        md5 = hashlib.md5()
        with open(file_path, 'rb') as f:
            while chunk := f.read(chunk_size):
                md5.update(chunk)
        return md5.hexdigest()
    except FileNotFoundError:
        logging.error(f""File not found: {file_path}"")
    except PermissionError:
        logging.error(f""No permission to read the file: {file_path}"")
    except Exception as e:
        logging.error(f""An error occurred while reading the file {file_path}: {e}"")

def compare_files(file1, file2):
    hash1 = calculate_md5_hash(file1)
    if hash1 is None:
        return False
    hash2 = calculate_md5_hash(file2)
    if hash2 is None:
        return False

    are_identical = hash1 == hash2
    logging.info(f""File 1: {file1}, File 2: {file2} - {'Identical' if are_identical else 'Not identical'}"")

    return are_identical
