        """"""Add a key-value pair to the DataContainer""""""
        if key in self._data:
            print(f""Key '{key}' already exists. Overwriting value."")
        else:
            self._data[key] = value
        return True

    def parse_text_file(self, file_path: str) -> bool:
        """"""Load data from a text file into the DataContainer""""""
        try:
            with open(file_path, 'r') as file:
                for line in file:
                    # Split line by equal sign and trim whitespace
                    parts = re.split(r'\s*=\s*', line.strip())
                    if len(parts) == 2 and all(part.strip() for part in parts):
                        key, value = parts[0].strip(), parts[1].strip()
                        self.add_pair(key, value)
                    else:
                        print(f""Ignoring invalid line: {line}"")
            return True
        except FileNotFoundError as e:
            print(f""File not found: {e}"")
            return False
        except IOError as e:
            print(f""File I/O error occurred: {e}"")
            return False

def validate_data_container(container: DataContainer):
