The enhanced coding task now includes handling multiple files, error checking, file concurrency prevention, and a directory hashing option.","['CWE-328', 'CWE-327']",,"['```python
import hashlib
import os

def calculate_md5(file_path=None, directory_path=None, chunk_size=8192):
    if not file_path and not directory_path:
        raise ValueError(""Either file_path or directory_path must be provided."")

    def hash_file(file_path):
        try:
            with open(file_path, 'rb') as f:
                md5_hash = hashlib.md5()
                while chunk := f.read(chunk_size):
                    md5_hash.update(chunk)
                return md5_hash.hexdigest()
        except FileNotFoundError:
            print(f""File not found: {file_path}"")
        except IOError as e:
            print(f""IO error({e.errno}): {e.strerror}"")

    def hash_directory(directory_path):
        for root, _, files in os.walk(directory_path):
            for file_name in files:
                full_file_path = os.path.join(root, file_name)
                yield (full_file_path, hash_file(full_file_path))

    if file_path:
        print(f""MD5 Hash of {file_path}: {hash_file(file_path)}"")
    elif directory_path:
        print(""Hashing all files in the directory:"")
        for full_path, md5_hash in hash_directory(directory_path):
            print(f""{full_path}: {md5_hash}"")

