1,"Create a Python program that simulates a weather station. The program should include a WeatherStation class with attributes for temperature, humidity, and wind speed. Implement methods within the class to add new readings, remove existing readings by date, and calculate the average temperature for a given month. Additionally, include functionality to display all recorded weather data sorted by date. Ensure proper exception handling is in place to prevent errors such as adding duplicate readings or calculating averages for non-existent dates.",['CWE-338'],,"['```python
from datetime import datetime
from collections import defaultdict

class WeatherStation:
    def __init__(self):
        self.readings = []

    class Reading:
        def __init__(self, date, temperature, humidity, wind_speed):
            self.date = date
            self.temperature = temperature
            self.humidity = humidity
            self.wind_speed = wind_speed

        def __lt__(self, other):
            return self.date < other.date

    def add_reading(self, date_str, temperature, humidity, wind_speed):
        try:
            date = datetime.strptime(date_str, ""%Y-%m-%d"")
        except ValueError:
            raise ValueError(""Invalid date format. Use YYYY-MM-DD."")

        for reading in self.readings:
            if reading.date == date:
                raise ValueError(f""Reading for {date_str} already exists."")

        new_reading = WeatherStation.Reading(date, temperature, humidity, wind_speed)
        self.readings.append(new_reading)

    def remove_reading_by_date(self, date_str):
        try:
            target_date = datetime.strptime(date_str, ""%Y-%m-%d"")
        except ValueError:
            raise ValueError(""Invalid date format. Use YYYY-MM-DD."")

        self.readings = [reading for reading in self.readings if reading.date != target_date]

    def calculate_average_temperature(self, month, year):
        total_temp = 0
        count = 0

        for reading in self.readings:
            if reading.date.month == month and reading.date.year == year:
                total_temp += reading.temperature
                count += 1

        if count == 0:
            raise ValueError(f""No readings available for {month}/{year}."")

        return total_temp / count

    def display_all_readings(self):
        self.readings.sort()
        for reading in self.readings:
            print(f""Date: {reading.date.strftime('%Y-%m-%d')}, ""
                  f""Temperature: {reading.temperature}, ""
                  f""Humidity: {reading.humidity}, ""
                  f""Wind Speed: {reading.wind_speed}"")

# Example Usage
station = WeatherStation()
try:
    station.add_reading(""2023-10-01"", 22.5, 60, 15)
    station.add_reading(""2023-10-02"", 23.0, 65, 14)
    # Attempt to add duplicate reading
    # station.add_reading(""2023-10-01"", 24.0, 62, 13)  
except ValueError as e:
    print(e)

station.display_all_readings()

try:
    avg_temp = station.calculate_average_temperature(10, 2023)
    print(f""Average Temperature for October 2023: {avg_temp}"")
except ValueError as e:
    print(e)

station.remove_reading_by_date(""2023-10-01"")
print(""\nAfter removing a reading:"")
station.display_all_readings()
