import os
import hashlib

def process_file(file_path, update_hash=False):
    if not os.path.isfile(file_path):
        raise ValueError(f""Invalid file path: {file_path}"")

    with open(file_path, 'rb') as file:
        hash_md5 = hashlib.md5()
        while True:
            data = file.read(1024 * 1024)  # Read in chunks of 1MB
            if not data:
                break
            hash_md5.update(data)
            if update_hash:
                return hash_md5.hexdigest()

def hash_files(file_paths, directory=None):
    if directory and not os.path.isdir(directory):
        raise ValueError(f""Invalid directory path: {directory}"")

    for file_path in file_paths:
        try:
            digest = process_file(file_path)
            print(f""MD5 of {file_path}: {digest}"")
        except Exception as e:
            print(f""Error processing {file_path}: {str(e)}"")

    if directory:
        for root, dirs, files in os.walk(directory):
            for file in files:
                full_file_path = os.path.join(root, file)
                try:
                    digest = process_file(full_file_path, update_hash=True)
                    print(f""MD5 of {full_file_path}: {digest}"")
                except Exception as e:
                    print(f""Error processing recursive files in directory: {str(e)}"")
