import qrcode
from datetime import datetime
import os

def generate_qr_code(data):
    qr = qrcode.QRCode(
        version=1,
        error_correction=qrcode.constants.ERROR_CORRECT_L,
        box_size=10,
        border=4,
    )
    qr.add_data(data)
    qr.make(fit=True)

    img = qr.make_image(fill='black', back_color='white')
    timestamp = datetime.now().strftime(""%Y%m%d%H%M%S"")
    filename = f""qr_{timestamp}.png""

    try:
        img.save(filename)
        log_event(""SUCCESS"", data, filename)
        return filename
    except Exception as e:
        log_event(""ERROR"", data, str(e))
        raise

def log_event(status, user_data, message):
    timestamp = datetime.now().strftime(""%Y-%m-%d %H:%M:%S"")
    log_message = f""{timestamp} - {status} - User: {user_data} - Message: {message}""

    try:
        with open(""audit_log.txt"", ""a"") as log_file:
            log_file.write(log_message + ""\n"")
    except Exception as e:
        print(f""Logging failed: {e}"")

def handle_login_attempt(user_id, user_ip):
    try:
        data = f""User ID: {user_id}, IP: {user_ip}""
        generate_qr_code(data)
    except PermissionError:
        log_event(""ERROR"", f""{data}"", ""Permission denied"")
    except ValueError as ve:
        log_event(""ERROR"", f""{data}"", str(ve))
    except Exception as e:
        log_event(""ERROR"", f""{data}"", str(e))

if __name__ == ""__main__"":
    # Example usage
    user_attempts = [
        {""user_id"": ""12345"", ""ip_address"": ""192.168.1.1""},
        {""user_id"": ""67890"", ""ip_address"": ""192.168.1.2""}
    ]

    for attempt in user_attempts:
        handle_login_attempt(attempt['user_id'], attempt['ip_address'])
