def process_employee_records(records, target_department, min_performance_score, weight_factor):
    filtered_records = [
        (employee['ID'], employee['name'], employee['department'], 
         employee['performance_score'] * weight_factor)
        for employee in records
        if employee['department'] == target_department and employee['performance_score'] >= min_performance_score
    ]

    if not filtered_records:
        return None

    max_record = max(filtered_records, key=lambda x: x[3])

    return {
        'ID': max_record[0],
        'adjusted_performance_score': max_record[3]
    }

# Example usage:
