    {'ID': 1, 'name': 'Alice', 'department': 'Sales', 'performance_score': 78},
    {'ID': 2, 'name': 'Bob', 'department': 'Engineering', 'performance_score': 85},
    {'ID': 3, 'name': 'Charlie', 'department': 'Sales', 'performance_score': 90}
]

result = process_employee_records(records, 'Sales', 80, 1.2)

