def item_exists(item_id):
    """"""Check if an item exists in the inventory.""""""
    return next((item for item in inventory if item[""id""] == item_id), None)

def reduce_stock(item, quantity):
    """"""Reduce stock quantity of a given item by the specified amount.""""""
    item[""stock_quantity""] -= quantity

def processOrderRequest(order_request):
    """"""Process an order request and update inventory as needed.""""""
    # Verify that all required fields are present and non-null
    required_fields = ['order_id', 'status', 'item_id', 'quantity']

    for field in required_fields:
        if field not in order_request or order_request[field] is None:
            return f""Error: Missing or null field '{field}'.""

    item = item_exists(order_request['item_id'])

    # Check if the item exists and there's sufficient stock
    if item:
        if item[""stock_quantity""] >= order_request['quantity']:
            reduce_stock(item, order_request['quantity'])
            return f""Success: Order processed. Updated stock for item {item['id']}: {item['stock_quantity']}""
        else:
            return ""Error: Insufficient stock to process the order.""
    else:
        return ""Error: Item not found in inventory.""

