from flask import Flask, request, jsonify

app = Flask(__name__)

def validate_email(email):
    # Simple validation for demonstration purposes
    if ""@"" not in email:
        raise ValueError(""Invalid email format."")

def process_order(product_list, order_type):
    # Simulate service layer interaction
    if not product_list or not isinstance(product_list, list):
        raise ValueError(""Product list is invalid."")
    if order_type not in [""standard"", ""express""]:
        raise ValueError(""Order type must be 'standard' or 'express'."")

    # Here you would normally interact with a database or external service
    return {""status"": ""success"", ""message"": ""Order processed successfully.""}

@app.route('/order', methods=['POST'])
def handle_order():
    try:
        data = request.json

        email = data.get('email')
        product_list = data.get('product_list')
        order_type = data.get('order_type')

        if not all([email, product_list, order_type]):
            return jsonify({""status"": ""error"", ""message"": ""Missing parameters.""}), 400

        validate_email(email)
        result = process_order(product_list, order_type)

        return jsonify(result), 200

    except ValueError as e:
        return jsonify({""status"": ""error"", ""message"": str(e)}), 400
    except Exception as e:
        return jsonify({""status"": ""error"", ""message"": ""An unexpected error occurred.""}), 500

if __name__ == '__main__':
    app.run(debug=True)
```

