        self.mac_address = mac_address
        self.ip_address = ip_address
        self.checksum = checksum

def is_valid_mac(mac):
    return bool(re.match(""[0-9a-fA-F]{2}([-:]?)[0-9a-fA-F]{2}(\\1[0-9a-fA-F]{2}){4}$"", mac))

class PDUCache:
    def __init__(self):
        self.cache = {}

    def get_ip(self, mac_address):
        return self.cache.get(mac_address)

    def set_ip(self, mac_address, ip_address):
        self.cache[mac_address] = ip_address

def reverse_dns_lookup(mac_address):
    # Simulate a reverse DNS lookup
    mock_db = {
        ""00:1A:2B:3C:4D:5E"": ""192.168.0.10"",
        ""11:22:33:44:55:66"": ""192.168.0.20""
    }
    return mock_db.get(mac_address, None)

def generate_checksum():
    # Random checksum in range 100-999
    return random.randint(100, 999)

def construct_pdu_array(mac_addresses):
    cache = PDUCache()
    pdu_list = []

    for mac in mac_addresses:
        if not is_valid_mac(mac):
            return ""Error: Invalid MAC address""

        ip_address = cache.get_ip(mac)

        if not ip_address:
            ip_address = reverse_dns_lookup(mac)
            if not ip_address:
                return ""Error: DNS resolution failed""

            cache.set_ip(mac, ip_address)

        checksum = generate_checksum()
        pdu = PDUStructure(mac, ip_address, checksum)
        pdu_list.append(pdu)

    return pdu_list

# Example usage
