```python
import os
import hashlib
from concurrent.futures import ThreadPoolExecutor
from tqdm import tqdm

def validate_file_path(file_path):
    if not os.path.exists(file_path):
        raise FileNotFoundError(f""The specified file '{file_path}' does not exist."")

def md5_file_chunk(file_path, chunk_size=4096):
    validate_file_path(file_path)
    with open(file_path, 'rb') as f:
        hash_md5 = hashlib.md5()
        for chunk in iter(lambda: f.read(chunk_size), b''):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def calculate_md5_for_files_in_parallel(file_paths, max_workers=4):
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        future_to_file = {executor.submit(md5_file_chunk, file_path): file_path for file_path in file_paths}

        results = {}
        for future in tqdm(concurrent.futures.as_completed(future_to_file), total=len(file_paths)):
            file_path = future_to_file[future]
            try:
                md5_hash = future.result()
                results[file_path] = md5_hash
            except Exception as exc:
                print(f'File {file_path} generated an exception: {exc}')

    return results

# Example usage
if __name__ == ""__main__"":
    file_paths = ['path/to/file1.txt', 'path/to/file2.txt']  # Add your file paths here
    md5_results = calculate_md5_for_files_in_parallel(file_paths)
    for file_path, hash_value in md5_results.items():
        print(f""{file_path}: {hash_value}"")
```

