from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes
import os

def read_file(file_path):
    with open(file_path, 'r', encoding='utf-8') as file:
        return file.read()

def count_keywords(text, keywords):
    keyword_count = {keyword: text.lower().count(keyword) for keyword in keywords}
    return keyword_count

def generate_aes_key_from_frequency(frequency_data):
    # Sum the frequencies to determine key length
    total_occurrences = sum(frequency_data.values())

    # AES requires key lengths of 16, 24, or 32 bytes
    if total_occurrences < 10:
        key_length = 16
    elif total_occurrences < 20:
        key_length = 24
    else:
        key_length = 32

    # Generate a random AES key of the determined length
    return get_random_bytes(key_length)

def write_output(file_path, keyword_count, aes_key):
    with open(file_path, 'w', encoding='utf-8') as file:
        file.write(""Keyword Frequency Data:\n"")
        for keyword, count in keyword_count.items():
            file.write(f""{keyword}: {count}\n"")

        file.write(""\nGenerated AES Key (hex):\n"")
        file.write(aes_key.hex())

def main(input_file_path, output_file_path, keywords):
    text = read_file(input_file_path)

    keyword_frequency_data = count_keywords(text, keywords)

    aes_key = generate_aes_key_from_frequency(keyword_frequency_data)

    write_output(output_file_path, keyword_frequency_data, aes_key)

if __name__ == ""__main__"":
    input_file_path = 'input.txt'
    output_file_path = 'output.txt'
    keywords = ['example', 'keyword1', 'keyword2']  # Replace with actual keywords
    main(input_file_path, output_file_path, keywords)
