import re

class DNSResolver:
    def __init__(self, capacity=10):
        self.cache = [{""host"": None, ""ip"": None} for _ in range(capacity)]
        self.last_index = -1

    def is_valid_ipv4(self, ip):
        pattern = r""^(?:[0-9]{1,3}\.){3}[0-9]{1,3}$""
        if re.match(pattern, ip):
            return all(0 <= int(part) < 256 for part in ip.split('.'))
        return False

    def is_valid_ipv6(self, ip):
        pattern = r""^([\da-fA-F]{1,4}:){7}[\da-fA-F]{1,4}$""
        return bool(re.match(pattern, ip))

    def validate_ip_address(self, ip):
        return self.is_valid_ipv4(ip) or self.is_valid_ipv6(ip)

    def add_host_ip_pair(self, host, ip):
        if not self.validate_ip_address(ip):
            raise ValueError(""Invalid IP address format"")

        for entry in self.cache:
            if entry[""host""] is None:
                entry[""host""] = host
                entry[""ip""] = ip
                return

        # If all slots are filled, use a circular buffer approach to overwrite the last entry.
        self.last_index = (self.last_index + 1) % len(self.cache)
        self.cache[self.last_index][""host""] = host
        self.cache[self.last_index][""ip""] = ip

    def find_empty_slot(self):
        for i, entry in enumerate(self.cache):
            if entry[""host""] is None:
                return i
        return -1


