            nmi_requests.append(nmi_request)

        return nmi_requests

    except MemoryError:
        return ""Error: Memory allocation failed.""

def clear_outdated_nmi_requests(nmi_requests, max_age_seconds=300):
    current_time = time.time()
    # Filter out outdated requests based on their age
    nmi_requests[:] = [req for req in nmi_requests if (current_time - req.timestamp) <= max_age_seconds]

def periodic_cleanup(nmi_requests, interval=60):
    Timer(interval, clear_outdated_nmi_requests, args=[nmi_requests]).start()
    # Recursively schedule the next cleanup
    periodic_cleanup(nmi_requests, interval)

# Usage Example:
