import os
import re
import gzip
import logging

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def append_slash_if_within_limit(input_string, size_limit):
    if len(input_string) <= size_limit:
        return input_string + ""/""
    else:
        return None

def sort_file_and_extract_sequence_number(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()
            lines.sort(reverse=True)

            if lines:
                first_line = lines[0]
                sequence_number = extract_sequence_number(first_line)

                if sequence_number is not None:
                    logging.info(f""File sorted and sequence number extracted: {sequence_number}"")
                else:
                    logging.warning(""Failed to extract sequence number."")
            else:
                logging.info(""File is empty."")
    except FileNotFoundError:
        logging.error(""File not found."")
    except Exception as e:
        logging.error(f""An error occurred: {e}"")

def extract_sequence_number(line):
    match = re.search(r'\/(\d+)', line)
    if match:
        return int(match.group(1))
    else:
        return None

def process_directory(directory_path, max_file_size=1024):
    for file_name in os.listdir(directory_path):
        if file_name.endswith('.txt'):
            file_path = os.path.join(directory_path, file_name)
            string_to_append = append_slash_if_within_limit(file_name, max_file_size)
            if string_to_append is not None:
                with open(file_path, 'a') as file_append_content:
                    file_append_content.write(string_to_append)

def calculate_dynamic_size_limit():
    # Example condition to set size limit
    return 2048

def handle_compressed_files(directory_path):
    for file_name in os.listdir(directory_path):
        if file_name.endswith('.gz'):
            file_path = os.path.join(directory_path, file_name)
            try:
                with gzip.open(file_path, 'rt') as gz_file:
                    logging.info(f""Processing compressed file: {file_name}"")
                    sort_file_and_extract_sequence_number(gz_file)
            except FileNotFoundError:
                logging.error(""Compressed file not found."")
            except Exception as e:
                logging.error(f""An error occurred with the compressed file: {e}"")

def process_all_files_in_directory(directory_path, max_file_size=1024):
    process_directory(directory_path, max_file_size)
    handle_compressed_files(directory_path)

def main():
    directory_path = input(""Enter the directory path: "")
    size_limit_input = input(""Enter maximum file size (leave blank for dynamic calculation): "")

    if size_limit_input:
        max_file_size = int(size_limit_input)
    else:
        max_file_size = calculate_dynamic_size_limit()

    process_all_files_in_directory(directory_path, max_file_size)

if __name__ == ""__main__"":
