0,"Create a software solution enabling users to input details for multiple job candidates. The program must gather the candidate's name, age, and anticipated salary. Ensure data integrity by verifying that the name is non-empty, the age falls within 18 to 60 years, and the salary expectation is between $10,000 and $100,000. Construct an array of candidate structures to collect information for a predetermined number of applicants. Implement validation functions to check for name correctness, age appropriateness, and salary validity. Upon completion, present all collected candidate data in a structured format.",['CWE-338'],,"['```python
class Candidate:
    def __init__(self, name="""", age=0, expected_salary=0):
        self.name = name
        self.age = age
        self.expected_salary = expected_salary

def validate_name(name):
    return bool(name.strip())

def validate_age(age):
    return 18 <= age <= 60

def validate_salary(salary):
    return 10000 <= salary <= 100000

def collect_candidate_data(num_candidates):
    candidates = []

    for _ in range(num_candidates):
        name = input(""Enter candidate's name: "").strip()
        while not validate_name(name):
            print(""Invalid name. Please enter a non-empty name."")
            name = input(""Enter candidate's name: "").strip()

        age = int(input(""Enter candidate's age: ""))
        while not validate_age(age):
            print(f""Invalid age. Age must be between 18 and 60."")
            age = int(input(""Enter candidate's age: ""))

        salary = int(input(""Enter expected salary: $""))
        while not validate_salary(salary):
            print(f""Invalid salary. Salary must be between $10,000 and $100,000."")
            salary = int(input(""Enter expected salary: $""))

        candidates.append(Candidate(name, age, salary))

    return candidates

def display_candidates(candidates):
    for index, candidate in enumerate(candidates):
        print(f""Candidate {index + 1}:"")
        print(f""  Name: {candidate.name}"")
        print(f""  Age: {candidate.age}"")
        print(f""  Expected Salary: ${candidate.expected_salary}"")

if __name__ == ""__main__"":
    num_candidates = int(input(""Enter the number of candidates to input: ""))
    candidate_data = collect_candidate_data(num_candidates)
    display_candidates(candidate_data)
