import sys

class Item:
    def __init__(self, name: str, price: float, stock_quantity: int):
        self.name = name
        self.price = price
        self.stock_quantity = stock_quantity

class InventoryManager:
    def __init__(self):
        self.items = []

    def add_item(self, item: Item):
        if any(existing_item.name == item.name for existing_item in self.items):
            raise ValueError(""Item already exists in inventory"")
        else:
            self.items.append(item)

    def remove_item(self, item_name: str):
        found_items = [item for item in self.items if item.name == item_name]
        if not found_items:
            raise ValueError(""Item not found in inventory"")
        self.items.remove(found_items[0])

    def update_stock(self, item_name: str, new_stock_quantity: int):
        for item in self.items:
            if item.name == item_name:
                if new_stock_quantity < 0:
                    raise ValueError(""Stock quantity cannot be negative"")
                else:
                    item.stock_quantity = new_stock_quantity
                    return
        raise ValueError(""Item not found in inventory"")

    def display_items(self):
        sorted_items = sorted(self.items, key=lambda x: x.price)
        for i in sorted_items:
            print(f""Name: {i.name}, Price: {i.price}, Stock Quantity: {i.stock_quantity}"")

def parse_args(args):
    if len(args) < 2 or (len(args) == 2 and args[1] != ""-h""):
        print(""Usage:"")
        print(""-h/--help      Print this help message"")
        # Assuming additional argument parsing logic will follow here
    elif args[1] in (""-c"", ""-cs""):
        # Placeholder for count lines of input file or similar functionality
        pass
    # Further command handling can be added here

def main():
    inventory_manager = InventoryManager()

    try:
        if len(sys.argv) > 2 and sys.argv[1] == ""--add"":
            item_name, price, stock_quantity = sys.argv[2], float(sys.argv[3]), int(sys.argv[4])
            inventory_manager.add_item(Item(item_name, price, stock_quantity))
        elif len(sys.argv) > 2 and sys.argv[1] == ""--remove"":
            item_name = sys.argv[2]
            inventory_manager.remove_item(item_name)
        elif len(sys.argv) > 3 and sys.argv[1] == ""--update-stock"":
            item_name, new_stock_quantity = sys.argv[2], int(sys.argv[3])
            inventory_manager.update_stock(item_name, new_stock_quantity)
        elif len(sys.argv) > 1 and sys.argv[1] == ""--display"":
            inventory_manager.display_items()
    except ValueError as e:
        print(f""Error: {e}"")

if __name__ == ""__main__"":
    parse_args(sys.argv)
    main()
