import random
from datetime import datetime

class DATE_T:
    def __init__(self, year, month, day, weekday):
        self.year = year
        self.month = month
        self.day = day
        self.weekday = weekday

    def is_valid_date(self):
        try:
            datetime(self.year, self.month, self.day)
            return True
        except ValueError:
            return False

def create_and_validate_random_dates(num_dates):
    date_list = []

    for _ in range(num_dates):
        year = random.randint(2000, 2100)
        month = random.randint(1, 12)

        # Determine the maximum possible day for the given month and year
        if month == 2:
            max_day = 29 if (year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)) else 28
        elif month in {4, 6, 9, 11}:
            max_day = 30
        else:
            max_day = 31

        day = random.randint(1, max_day)
        weekday = random.randint(1, 7)  # Simulated as [1, 2, ..., 7]

        date_instance = DATE_T(year, month, day, weekday)

        if date_instance.is_valid_date():
            date_list.append(date_instance)

    return date_list

# Example usage
random_dates = create_and_validate_random_dates(10)
for date in random_dates:
