This integrated approach combines book collection management from Prompt 1 with transaction processing from Prompt 2 into a single powerful system. By merging these functionalities under one roof using well-structured classes and methods that handle concurrency through synchronization mechanisms like mutexes, this solution offers a robust platform for managing libraries under concurrent access scenarios while supporting international languages.",['CWE-242'],,"['```python
import threading
from typing import List, Optional

class Book:
    def __init__(self, title: str, author: str, publication_year: int, unique_id: str):
        self.title = title
        self.author = author
        self.publication_year = publication_year
        self.sort_criteria = None  # 'title', 'author', or 'year'
        self.sort_order = None     # 'ascending' or 'descending'
        self.unique_id = unique_id

    def __repr__(self):
        return f""Book(title={self.title}, author={self.author}, year={self.publication_year})""

class LibraryCollection:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.books = []
        self.lock = threading.Lock()

    def add_book(self, book: Book) -> Optional[str]:
        with self.lock:
            if len(self.books) >= self.capacity:
                return ""Error: Collection is full.""
            self.books.append(book)
            return None

    def remove_book(self, unique_id: str) -> bool:
        with self.lock:
            for i, book in enumerate(self.books):
                if book.unique_id == unique_id:
                    del self.books[i]
                    return True
            return False

    def sort_books(self, by: str, order: str = 'ascending'):
        with self.lock:
            valid_criteria = ['title', 'author', 'year']
            valid_order = ['ascending', 'descending']

            if by not in valid_criteria or order not in valid_order:
                raise ValueError(""Invalid sort criteria or order."")

            reverse = (order == 'descending')
            key_func = {
                'title': lambda book: book.title,
                'author': lambda book: book.author,
                'year': lambda book: book.publication_year
            }[by]

            self.books.sort(key=key_func, reverse=reverse)
            for book in self.books:
                book.sort_criteria = by
                book.sort_order = order

    def search_books(self, keyword: str) -> List[Book]:
        with self.lock:
            return [book for book in self.books if keyword.lower() in book.title.lower() or keyword.lower() in book.author.lower()]

class LibrarySystem:
    def __init__(self, capacity: int):
        self.collection = LibraryCollection(capacity)
        self.transactions_log = []

    def add_book(self, title: str, author: str, publication_year: int, unique_id: str) -> Optional[str]:
        if not title or not author:
            return ""Error: Title and Author cannot be empty.""

        book = Book(title, author, publication_year, unique_id)
        error_message = self.collection.add_book(book)
        if not error_message:
            self.transactions_log.append(f""Added book: {book}"")
        return error_message

    def remove_book(self, unique_id: str):
        removed = self.collection.remove_book(unique_id)
        if removed:
            self.transactions_log.append(f""Removed book with ID: {unique_id}"")

    def sort_books(self, by: str, order: str = 'ascending'):
        try:
            self.collection.sort_books(by, order)
            self.transactions_log.append(f""Sorted books by {by} in {order} order."")
        except ValueError as e:
            print(e)

    def search_books(self, keyword: str) -> List[Book]:
        return self.collection.search_books(keyword)

    def save_load_library(self, file_path: str):
        # Implementation for saving/loading the library state to/from a file
        pass

# Example usage
library_system = LibrarySystem(capacity=100)
print(library_system.add_book(""Python Programming"", ""John Doe"", 2020, ""001""))
library_system.sort_books(by=""title"")
books = library_system.search_books(keyword=""python"")
for book in books:
    print(book)
```']",452,[0],[],True,0,0,0,

