import random
from datetime import datetime, timedelta

class ProductStock:
    def __init__(self, product_id, stock_quantity, restock_date):
        self.product_id = product_id
        self.stock_quantity = stock_quantity
        self.restock_date = restock_date

def generate_random_dates(start_date):
    current_date = start_date
    date_list = []
    for _ in range(100):
        random_days_diff = random.randint(30, 180)
        date_list.append(current_date + timedelta(days=random_days_diff))
        current_date += timedelta(days=random_days_diff)
    return date_list

def create_product_stock_list(num_products):
    products_dict = {}
    start_stock_dates = generate_random_dates(datetime(2023, 1, 1))

    for _ in range(num_products):
        product_id = ''.join(random.choices('ABCDEFGHIJKLMNOPQRSTUVWXYZ', k=5))
        stock_quantity = random.randint(10, 50)
        restock_date_index = random.randint(0, len(start_stock_dates) - 1)

        # Ensuring the restock date is within the valid range of generated dates.
        while restock_date_index < len(start_stock_dates) - 99:
            restock_date_index += random.randint(3, 7)

        if restock_date_index >= len(start_stock_dates):
            break

        stock_with_restock_info = {
            'product_id': product_id,
            'stock_quantity': stock_quantity,
            'restock_date': start_stock_dates[restock_date_index]
        }

        products_dict[product_id] = stock_with_restock_info

    return list(products_dict.values())

