from queue import Queue

class ReplicationManager:
    def __init__(self):
        self.tasks = {}

    def schedule_task(self, dataset_id, interval):
        task_id = f""task_{dataset_id}_{random.randint(1, 1000)}""
        self.tasks[task_id] = {
            'dataset_id': dataset_id,
            'interval': interval,
            'last_run': time.time()
        }
        threading.Thread(target=self.run_task, args=(task_id,)).start()

    def run_task(self, task_id):
        while True:
            current_time = time.time()
            if current_time - self.tasks[task_id]['last_run'] >= self.tasks[task_id]['interval']:
                # Simulate data replication
                print(f""Replicating data for {self.tasks[task_id]['dataset_id']}..."")
                self.tasks[task_id]['last_run'] = current_time
                time.sleep(self.tasks[task_id]['interval'])

