from fastapi import FastAPI, HTTPException, Depends, Query, Body
from pydantic import BaseModel, Field
from typing import Optional, List, Dict
import uuid
import datetime
import jwt
import redis
from functools import wraps

# Initialize the app and Redis cache
app = FastAPI()
redis_cache = redis.Redis(host='localhost', port=6379, db=0)

# Models
class Resource(BaseModel):
    id: str
    data: Dict[str, str]
    version: int
    is_deleted: bool = False

class UpdateResourceRequest(BaseModel):
    id: str
    updated_data: Dict[str, str]
    condition: Optional[Dict[str, str]] = None

class DeleteResourceRequest(BaseModel):
    id: str
    soft_delete: bool = False

# Mock database
resources_db = {}

# Authentication and Authorization
def token_required(func):
    @wraps(func)
    async def wrapper(*args, **kwargs):
        # Extract token from headers (simplified for this example)
        token = ""mock_token""
        try:
            payload = jwt.decode(token, 'secret', algorithms=['HS256'])
            user_id = payload['user_id']
        except jwt.ExpiredSignatureError:
            raise HTTPException(status_code=403, detail=""Token expired"")
        except jwt.InvalidTokenError:
            raise HTTPException(status_code=403, detail=""Invalid token"")

        # Simulated user roles
        roles = ['admin', 'editor']  # Example roles

        return await func(user_id=user_id, roles=roles, *args, **kwargs)
    return wrapper

# Concurrency handling: Optimistic locking and versioning
def check_version(resource: Resource, requested_version: int):
    if resource.version != requested_version:
        raise HTTPException(status_code=409, detail=""Version conflict"")

@app.put(""/resource/{id}"", dependencies=[Depends(token_required)])
async def update_resource(id: str, request: UpdateResourceRequest, user_id: str, roles: List[str], version: int = Body(...)):
    resource = resources_db.get(id)

    if not resource:
        raise HTTPException(status_code=404, detail=""Resource not found"")

    # Check conditions
    if request.condition:
        for key, value in request.condition.items():
            if resource.data.get(key) != value:
                return {""status"": ""unchanged""}

    check_version(resource, version)

    # Update and increment version
    resource.data.update(request.updated_data)
    resource.version += 1

    resources_db[id] = resource

    log_action(user_id, 'update', id, {'version': resource.version})
    return resource

@app.delete(""/resource/{id}"", dependencies=[Depends(token_required)])
async def delete_resource(id: str, request: DeleteResourceRequest, user_id: str, roles: List[str]):
    resource = resources_db.get(id)

    if not resource:
        raise HTTPException(status_code=404, detail=""Resource not found"")

    # Check for dependencies (mock logic)
    if ""dependent"" in resource.data.values():
        raise HTTPException(status_code=400, detail=""Cannot delete a resource with active dependencies"")

    if request.soft_delete:
        resource.is_deleted = True
    else:
        del resources_db[id]

    log_action(user_id, 'delete', id, {'soft_delete': request.soft_delete})
    return {""status"": ""deleted""}

# Logging and Audit Trails
def log_action(user_id: str, action: str, resource_id: str, details: Dict[str, str]):
    timestamp = datetime.datetime.utcnow().isoformat()
    log_entry = {
        'user_id': user_id,
        'action': action,
        'resource_id': resource_id,
        'details': details,
        'timestamp': timestamp
    }
    # Simplified logging

