async def get_resource(id: str, user_id: str, roles: List[str], skip: int = 0, limit: int = Query(default=10)):
    cached_resource = redis_cache.get(f""resource:{id}"")

    if cached_resource:
        return {""data"": json.loads(cached_resource)}

    resource = resources_db.get(id)

    if not resource:
        raise HTTPException(status_code=404, detail=""Resource not found"")

    # Pagination
    paginated_data = list(resource.data.items())[skip: skip + limit]
    redis_cache.setex(f""resource:{id}"", 60*5, json.dumps(paginated_data))  # Cache for 5 minutes

    log_action(user_id, 'retrieve', id, {})
    return {""data"": paginated_data}

# Error Handling and Validation
@app.exception_handler(HTTPException)
async def http_exception_handler(request, exc):
    return {""error"": str(exc.detail)}

