from flask import Flask, request, jsonify

app = Flask(__name__)

def validate_email(email):
    # Simple validation for email format (for demonstration)
    if ""@"" not in email:
        return False
    return True

def process_order(email, product_list, order_type):
    # Simulate processing the order by returning a success message
    return f""Order processed: {email}, {product_list}, {order_type}""

@app.route('/process-order', methods=['POST'])
def handle_post_request():
    data = request.json

    email = data.get('email')
    product_list = data.get('product_list')
    order_type = data.get('order_type')

    if not email or not validate_email(email):
        return jsonify({'error': 'Invalid email'}), 400
    if not product_list or not isinstance(product_list, list):
        return jsonify({'error': 'Product list is required and must be a list'}), 400
    if not order_type:
        return jsonify({'error': 'Order type is required'}), 400

    try:
        confirmation_message = process_order(email, product_list, order_type)
        return jsonify({'confirmation': confirmation_message}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
```

