import random

def generate_security_tokens():
    access_levels = ['admin', 'user', 'guest']
    encryption_types = ['AES-256', 'RSA-2048', 'TLS 1.3']
    data_transfer_limits = ['10GB', '50GB', '100GB']

    return {
        ""access_level"": random.choice(access_levels),
        ""encryption_type"": random.choice(encryption_types),
        ""data_transfer_limit"": random.choice(data_transfer_limits)
    }

def generate_server_configurations(servers):
    server_list = []

    for server_name, details in servers.items():
        security_tokens = [generate_security_tokens() for _ in range(random.randint(1, 5))]

        server_configuration = {
            'name': server_name,
            'ip_address': details['ip_address'],
            'port_number': details['port_number'],
            'protocol_version': details['protocol_version'],
            'auth_key': details['auth_key'],
            'security_tokens': security_tokens
        }

        server_list.append(server_configuration)

    return server_list

